namespace PeakSWC.RemoteBlazorWebView.SourceGenerators
{
    /// <summary>The types every project that uses the generator gets: the attribute, its mode and the command line reader. They are
    /// internal, so two projects that both use the generator never clash.</summary>
    internal static class PostInitializationSources
    {
        public const string AttributeMetadataName = "PeakSWC.RemoteBlazorWebView.RemoteBlazorAttribute";

        public const string HintName = "RemoteBlazorAttribute.g.cs";

        public const string Text = """
// <auto-generated/> by PeakSWC.RemoteBlazorWebView.SourceGenerators
#nullable enable

namespace PeakSWC.RemoteBlazorWebView
{
    /// <summary>Whether the code generated for <see cref="RemoteBlazorAttribute"/> makes the BlazorWebView remote.</summary>
    internal enum RemoteBlazorMode
    {
        /// <summary>Remote when the app is started with <c>-u=&lt;server uri&gt;</c>, otherwise local. The default.</summary>
        Runtime = 0,
        /// <summary>Always local: the generated InitializeRemoteBlazor() does nothing.</summary>
        Local = 1,
        /// <summary>Always remote, on <c>-u=&lt;server uri&gt;</c> when given, otherwise on <see cref="RemoteBlazorAttribute.ServerUri"/>.</summary>
        Remote = 2,
    }

    /// <summary>
    /// Generates <c>bool InitializeRemoteBlazor()</c> for this window, form or control. Call it after <c>InitializeComponent()</c>.
    /// It sets up the named PeakSWC BlazorWebView for remote use (the code-behind steps of the RemoteBlazorWebViewTutorial's
    /// ConvertToRemoteBlazor.md) and returns whether the view is remote. The <c>RemoteBlazorMode</c> MSBuild property
    /// (Local, Remote or Runtime), when set, overrides <see cref="Mode"/>.
    /// </summary>
    [global::System.AttributeUsage(global::System.AttributeTargets.Class, Inherited = false, AllowMultiple = false)]
    [global::System.Diagnostics.Conditional("REMOTE_BLAZOR_ATTRIBUTES")]
    internal sealed class RemoteBlazorAttribute : global::System.Attribute
    {
        /// <param name="webView">The name of the field or property that holds the BlazorWebView, e.g. <c>nameof(RemoteBlazorWebView)</c>.</param>
        public RemoteBlazorAttribute(string webView) { WebView = webView; }

        /// <summary>The name of the field or property that holds the BlazorWebView.</summary>
        public string WebView { get; }

        /// <summary>Local, Remote, or Runtime (the default: remote only when started with -u=).</summary>
        public RemoteBlazorMode Mode { get; set; }

        /// <summary>The RemoteWebViewService to use in Remote mode when there is no -u= on the command line, e.g. "https://localhost:5001".</summary>
        public string? ServerUri { get; set; }

        /// <summary>A fixed client id (a Guid). Without it, and without -i= on the command line, each run gets a new id.</summary>
        public string? Id { get; set; }

        /// <summary>Show the link to the app (&lt;server&gt;/app/&lt;id&gt;) in the BlazorWebView until a browser connects. Default true.</summary>
        public bool ShowLink { get; set; } = true;

        /// <summary>Once a browser connects, show a read-only mirror of the remote UI in the BlazorWebView.</summary>
        public bool Mirror { get; set; }

        /// <summary>
        /// Reverse mirror: the name of a WebView2 control you put over the BlazorWebView (in XAML or the WinForms designer). The person
        /// at the PC uses the app in that WebView2, through the server, so the window looks and works like a local app; once it
        /// connects, the system browser opens the read-only mirror (&lt;server&gt;/mirror/&lt;id&gt;), the view to share. Replaces
        /// ShowLink; can't be combined with Mirror.
        /// </summary>
        public string? ReverseMirror { get; set; }

        /// <summary>When the browser is refreshed, start a fresh copy of the app on the same server and id, and close this window.</summary>
        public bool RestartOnRefresh { get; set; }

        /// <summary>When the browser disconnects (tab closed, navigated away), shut the app down.</summary>
        public bool ShutdownOnDisconnect { get; set; }
    }

    /// <summary>Reads the RemoteBlazorWebView command line: <c>-u=&lt;server uri&gt;</c> and <c>-i=&lt;id&gt;</c> (also <c>--u=</c>,
    /// <c>/u=</c> and <c>-u &lt;value&gt;</c>). It's the convention BlazorWebView.Restart() uses to start the new copy.</summary>
    internal static class RemoteBlazorCommandLine
    {
        /// <summary>The -u= server uri, or null when there is none (or it isn't an absolute uri).</summary>
        public static global::System.Uri? ServerUri =>
            global::System.Uri.TryCreate(Value("u"), global::System.UriKind.Absolute, out var uri) ? uri : null;

        /// <summary>The -i= client id, or null when there is none (or it isn't a Guid).</summary>
        public static global::System.Guid? Id =>
            global::System.Guid.TryParse(Value("i"), out var id) ? id : null;

        /// <summary>The value of the named switch, or null.</summary>
        public static string? Value(string name)
        {
            var args = global::System.Environment.GetCommandLineArgs();
            for (var i = 1; i < args.Length; i++)
            {
                var arg = args[i];
                var start = arg.StartsWith("--", global::System.StringComparison.Ordinal) ? 2
                    : arg.StartsWith("-", global::System.StringComparison.Ordinal) || arg.StartsWith("/", global::System.StringComparison.Ordinal) ? 1 : 0;
                if (start == 0) continue;
                var body = arg.Substring(start);
                if (body.StartsWith(name + "=", global::System.StringComparison.OrdinalIgnoreCase)) return body.Substring(name.Length + 1);
                if (string.Equals(body, name, global::System.StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length) return args[i + 1];
            }
            return null;
        }
    }
}
""";
    }
}
